CALL SP_DEDUPLICA_EDITORIAL_FINALIZA(
    {{ $('Similaridade Editorial v0.4.0').item.json.registro_id }},
    'PUBLICADO',
    'Publicação concluída com sucesso no Core Editorial',
    '{{ $execution.id }}'
);

CALL SP_DEDUPLICA_EDITORIAL_FINALIZA(
    {{ $('Similaridade Editorial v0.4.0').item.json.registro_id }},
    'DUPLICADO',
    '{{ 
      "Score: " 
      + $('Similaridade Editorial v0.4.0').item.json.duplicidade_editorial.percentual
      + "% | Match: "
      + ($('Similaridade Editorial v0.4.0').item.json.duplicidade_editorial.melhor_match?.titulo || "")
