// ============================================================
// CODE | Consenso Editorial v0.1.0
// Modo: Run Once for All Items
//
// Objetivo:
// - Gerar insumos analíticos para alertas de SUSPEITO
// - NÃO alterar a decisão funcional do Core
// - NÃO alterar roteamento
// - Avaliar convergência entre TOP matches
// - Identificar consenso multifonte
//
// Fonte oficial:
// $('Similaridade Editorial v0.4.0').first().json
//
// Fase atual:
// HOMOLOGAÇÃO ANALÍTICA
// ============================================================


// ============================================================
// 1. RECUPERA RESULTADO DA SIMILARIDADE
// ============================================================

let origem = {};

try {

  origem =
    $('Similaridade Editorial v0.4.0')
      .first()
      .json ?? {};

} catch (error) {

  throw new Error(
    'Consenso Editorial v0.1.0: ' +
    'não foi possível recuperar a saída de ' +
    'Similaridade Editorial v0.4.0.'
  );
}


// ============================================================
// 2. CONTRATOS
// ============================================================

const duplicidade =
  origem.duplicidade_editorial &&
  typeof origem.duplicidade_editorial === 'object'
    ? origem.duplicidade_editorial
    : {};

const topMatches =
  Array.isArray(duplicidade.top_matches)
    ? duplicidade.top_matches
    : [];


// ============================================================
// 3. CONFIGURAÇÃO ANALÍTICA
//
// IMPORTANTE:
// Esta configuração NÃO decide o fluxo.
// Apenas gera hipótese/sugestão para auditoria.
// ============================================================

const CONFIG = {

  versao:
    '0.1.0',

  modo:
    'HOMOLOGACAO_ANALITICA',

  // Regra de consenso forte
  consensoForte: {

    scoreTop1Min:
      0.70,

    scoreTop2Min:
      0.70,

    tokensTop1Min:
      5,

    coberturaTop1Min:
      0.80,

    exigirFontesDistintas:
      true

  },

  // Regra de consenso moderado
  consensoModerado: {

    scoreTop1Min:
      0.62,

    scoreTop2Min:
      0.55,

    tokensTop1Min:
      4,

    coberturaTop1Min:
      0.65

  }

};


// ============================================================
// 4. HELPERS
// ============================================================

function numero(valor, fallback = 0) {

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : fallback;
}


function percentual(valor) {

  return Number(
    (
      numero(valor) * 100
    ).toFixed(2)
  );
}


function getScore(match) {

  return numero(
    match?.metricas?.score_composto
  );
}


function getPercentual(match) {

  const p =
    match?.metricas?.percentual;

  if (
    p !== null &&
    p !== undefined &&
    Number.isFinite(Number(p))
  ) {

    return Number(p);
  }

  return percentual(
    getScore(match)
  );
}


function getTokensComuns(match) {

  return numero(
    match?.metricas?.tokens_comuns
  );
}


function getCobertura(match) {

  return numero(
    match
      ?.metricas
      ?.cobertura_titulo_menor
  );
}


function getOrigem(match) {

  return String(
    match?.origem ??
    ''
  )
    .trim()
    .toLowerCase() || null;
}


// ============================================================
// 5. TOP 1 / TOP 2 / TOP 3
// ============================================================

const top1 =
  topMatches[0] ?? null;

const top2 =
  topMatches[1] ?? null;

const top3 =
  topMatches[2] ?? null;


// ============================================================
// 6. MÉTRICAS DERIVADAS
// ============================================================

const scoreTop1 =
  getScore(top1);

const scoreTop2 =
  getScore(top2);

const scoreTop3 =
  getScore(top3);


const percentualTop1 =
  getPercentual(top1);

const percentualTop2 =
  getPercentual(top2);

const percentualTop3 =
  getPercentual(top3);


const tokensTop1 =
  getTokensComuns(top1);

const tokensTop2 =
  getTokensComuns(top2);

const tokensTop3 =
  getTokensComuns(top3);


const coberturaTop1 =
  getCobertura(top1);

const coberturaTop2 =
  getCobertura(top2);

const coberturaTop3 =
  getCobertura(top3);


const origemTop1 =
  getOrigem(top1);

const origemTop2 =
  getOrigem(top2);

const origemTop3 =
  getOrigem(top3);


// ============================================================
// 7. DIVERSIDADE DE FONTES
// ============================================================

const fontesTop3 =
  [
    origemTop1,
    origemTop2,
    origemTop3
  ]
    .filter(Boolean);


const fontesDistintas =
  [
    ...new Set(
      fontesTop3
    )
  ];


const totalFontesDistintas =
  fontesDistintas.length;


const top1Top2FontesDistintas =
  Boolean(
    origemTop1 &&
    origemTop2 &&
    origemTop1 !== origemTop2
  );


// ============================================================
// 8. GAP TOP1 x TOP2
// ============================================================

const gapTop1Top2 =
  Math.max(
    0,
    scoreTop1 - scoreTop2
  );


const percentualGapTop1Top2 =
  Number(
    (
      gapTop1Top2 * 100
    ).toFixed(2)
  );


// ============================================================
// 9. REGRA DE CONSENSO FORTE
// ============================================================

const regraForte =
  (
    scoreTop1 >=
      CONFIG.consensoForte.scoreTop1Min
  )
  &&
  (
    scoreTop2 >=
      CONFIG.consensoForte.scoreTop2Min
  )
  &&
  (
    tokensTop1 >=
      CONFIG.consensoForte.tokensTop1Min
  )
  &&
  (
    coberturaTop1 >=
      CONFIG.consensoForte.coberturaTop1Min
  )
  &&
  (
    !CONFIG.consensoForte.exigirFontesDistintas
    ||
    top1Top2FontesDistintas
  );


// ============================================================
// 10. REGRA DE CONSENSO MODERADO
// ============================================================

const regraModerada =
  (
    scoreTop1 >=
      CONFIG.consensoModerado.scoreTop1Min
  )
  &&
  (
    scoreTop2 >=
      CONFIG.consensoModerado.scoreTop2Min
  )
  &&
  (
    tokensTop1 >=
      CONFIG.consensoModerado.tokensTop1Min
  )
  &&
  (
    coberturaTop1 >=
      CONFIG.consensoModerado.coberturaTop1Min
  );


// ============================================================
// 11. CLASSIFICAÇÃO ANALÍTICA
//
// IMPORTANTE:
// Isso NÃO substitui:
// duplicidade_editorial.status
// ============================================================

let nivelConsenso =
  'BAIXO';

let statusSugerido =
  'SUSPEITO';

let motivo =
  'SEM_CONSENSO_FORTE';


if (regraForte) {

  nivelConsenso =
    'FORTE';

  statusSugerido =
    'DUPLICADO';

  motivo =
    'CONSENSO_MULTIFONTE_FORTE';

} else if (regraModerada) {

  nivelConsenso =
    'MODERADO';

  statusSugerido =
    'SUSPEITO';

  motivo =
    'CONSENSO_SEMANTICO_MODERADO';

}


// ============================================================
// 12. SINAIS ANALÍTICOS
// ============================================================

const sinais = {

  dois_matches_acima_70:
    (
      scoreTop1 >= 0.70 &&
      scoreTop2 >= 0.70
    ),

  cinco_tokens_top1:
    tokensTop1 >= 5,

  cobertura_top1_acima_80:
    coberturaTop1 >= 0.80,

  fontes_top1_top2_distintas:
    top1Top2FontesDistintas,

  tres_fontes_distintas_top3:
    totalFontesDistintas >= 3,

  gap_top1_top2_baixo:
    gapTop1Top2 <= 0.05,

  top3_ainda_relevante:
    scoreTop3 >= 0.55

};


// ============================================================
// 13. RESUMO TEXTUAL
// ============================================================

let resumo =
  'Similaridade relevante, mas sem consenso multifonte forte.';


if (
  nivelConsenso === 'FORTE'
) {

  resumo =
    'Há forte convergência semântica entre múltiplas fontes. ' +
    'O caso é forte candidato a duplicidade editorial real.';

} else if (
  nivelConsenso === 'MODERADO'
) {

  resumo =
    'Há convergência semântica moderada entre os melhores matches. ' +
    'Recomenda-se revisão editorial.';

}


// ============================================================
// 14. SAÍDA
//
// Mantemos TODO o JSON da Similaridade.
// Apenas adicionamos consenso_editorial.
// ============================================================

return [
  {
    json: {

      ...origem,

      consenso_editorial: {

        versao:
          CONFIG.versao,

        modo:
          CONFIG.modo,

        aplicado_automaticamente:
          false,

        altera_status_core:
          false,

        status_original:
          duplicidade.status ?? null,

        status_sugerido:
          statusSugerido,

        nivel:
          nivelConsenso,

        motivo,

        resumo,


        // ------------------------------------------------------
        // TOP 1
        // ------------------------------------------------------

        top1: {

          id:
            top1?.id ?? null,

          titulo:
            top1?.titulo ?? null,

          origem:
            origemTop1,

          score:
            scoreTop1,

          percentual:
            percentualTop1,

          tokens_comuns:
            tokensTop1,

          cobertura:
            coberturaTop1,

          cobertura_percentual:
            percentual(
              coberturaTop1
            )

        },


        // ------------------------------------------------------
        // TOP 2
        // ------------------------------------------------------

        top2: {

          id:
            top2?.id ?? null,

          titulo:
            top2?.titulo ?? null,

          origem:
            origemTop2,

          score:
            scoreTop2,

          percentual:
            percentualTop2,

          tokens_comuns:
            tokensTop2,

          cobertura:
            coberturaTop2,

          cobertura_percentual:
            percentual(
              coberturaTop2
            )

        },


        // ------------------------------------------------------
        // TOP 3
        // ------------------------------------------------------

        top3: {

          id:
            top3?.id ?? null,

          titulo:
            top3?.titulo ?? null,

          origem:
            origemTop3,

          score:
            scoreTop3,

          percentual:
            percentualTop3,

          tokens_comuns:
            tokensTop3,

          cobertura:
            coberturaTop3,

          cobertura_percentual:
            percentual(
              coberturaTop3
            )

        },


        // ------------------------------------------------------
        // CONSENSO
        // ------------------------------------------------------

        consenso: {

          multifonte:
            totalFontesDistintas >= 2,

          fontes_top1_top2_distintas:
            top1Top2FontesDistintas,

          total_fontes_distintas_top3:
            totalFontesDistintas,

          fontes_distintas_top3:
            fontesDistintas,

          gap_top1_top2:
            Number(
              gapTop1Top2.toFixed(4)
            ),

          percentual_gap_top1_top2:
            percentualGapTop1Top2

        },


        // ------------------------------------------------------
        // SINAIS
        // ------------------------------------------------------

        sinais,


        // ------------------------------------------------------
        // REGRAS AUDITADAS
        // ------------------------------------------------------

        regras: {

          consenso_forte: {

            atingido:
              regraForte,

            score_top1_min:
              CONFIG.consensoForte.scoreTop1Min,

            score_top2_min:
              CONFIG.consensoForte.scoreTop2Min,

            tokens_top1_min:
              CONFIG.consensoForte.tokensTop1Min,

            cobertura_top1_min:
              CONFIG.consensoForte.coberturaTop1Min,

            exigir_fontes_distintas:
              CONFIG.consensoForte.exigirFontesDistintas

          },

          consenso_moderado: {

            atingido:
              regraModerada,

            score_top1_min:
              CONFIG.consensoModerado.scoreTop1Min,

            score_top2_min:
              CONFIG.consensoModerado.scoreTop2Min,

            tokens_top1_min:
              CONFIG.consensoModerado.tokensTop1Min,

            cobertura_top1_min:
              CONFIG.consensoModerado.coberturaTop1Min

          }

        }

      }

    }
  }
];

// n8n: Run Once for All Items. Uma saida mesmo sem regras.
const rows = [];
const vistos = new WeakSet();
function coletar(valor) {
  if (!valor || typeof valor !== 'object' || vistos.has(valor)) return;
  vistos.add(valor);
  if (Array.isArray(valor)) return valor.forEach(coletar);
  if (Object.prototype.hasOwnProperty.call(valor, 'regra_id')) { rows.push(valor); return; }
  Object.values(valor).forEach(coletar);
}
for (const item of $input.all()) coletar(item.json);
const ids = new Set();
const expressoes = new Set();
let erro = null;
const regras = [];
for (const r of rows) {
  const id = Number(r.regra_id), prioridade = Number(r.prioridade), confianca = Number(r.confianca);
  const expressao = String(r.expressao ?? '').trim();
  const canonico = String(r.valor_canonico ?? '').trim();
  const chave = expressao.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (r.dsc_dominio !== 'ENERGIA_LIMPA' || r.dsc_consumidor !== 'PEL' ||
      r.versao_vocabulario !== '0.1.0' || r.tipo !== 'FACETA_EDITORIAL' ||
      r.tipo_expressao !== 'LITERAL' || Number(r.ativo) !== 1 ||
      !Number.isSafeInteger(id) || id <= 0 || ids.has(id) || expressoes.has(chave) ||
      !expressao || !/^[A-Z][A-Z0-9_]*$/.test(canonico) ||
      !Number.isInteger(prioridade) || prioridade < 0 || prioridade > 100 ||
      !Number.isFinite(confianca) || confianca < 0 || confianca > 1) {
    erro = 'REGRA_INVALIDA_OU_AMBIGUA'; break;
  }
  ids.add(id); expressoes.add(chave);
  regras.push({regra_id: id, expressao, valor_canonico: canonico, prioridade, confianca});
}
if (rows.length > 500) erro = 'LIMITE_DE_REGRAS_EXCEDIDO';
return [{json: {vocabulario_editorial: {
  dominio: 'ENERGIA_LIMPA', consumidor: 'PEL', versao: '0.1.0',
  status: erro || (regras.length ? 'CARREGADO' : 'VAZIO'),
  modo: 'OBSERVACAO', total_regras: erro ? 0 : regras.length,
  regras: erro ? [] : regras
}}}];

// n8n: Run Once for All Items. Colocar entre Merge e Similaridade PEL v0.4.0.
// Somente auditoria: nao altera candidato, comparaveis ou decisao lexical.
const entrada = $input.first()?.json ?? {};
const vocab = entrada.vocabulario_editorial;
const valido = vocab?.dominio === 'ENERGIA_LIMPA' && vocab?.consumidor === 'PEL' &&
  vocab?.versao === '0.1.0' && vocab?.status === 'CARREGADO' && Array.isArray(vocab.regras);
function normalizar(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
}
function detectar(titulo) {
  const texto = ` ${normalizar(titulo)} `;
  const matches = (valido ? vocab.regras : []).filter(r => {
    const termo = normalizar(r.expressao);
    return termo && texto.includes(` ${termo} `);
  });
  return {facetas: [...new Set(matches.map(r => r.valor_canonico))],
    ids_regras: matches.map(r => r.regra_id)};
}
const candidato = entrada.candidato ?? {};
const comparaveis = Array.isArray(entrada.comparaveis) ? entrada.comparaveis : [];
return [{json: {...entrada, contexto_vocabulario_pel: {
  versao: '0.1.0', modo: 'OBSERVACAO', fonte: valido ? 'BANCO' : 'INDISPONIVEL',
  status: vocab?.status ?? 'AUSENTE', aplicado_na_decisao: false,
  total_regras: valido ? vocab.regras.length : 0,
  candidato: detectar(candidato.titulo),
  comparaveis: comparaveis.map(c => ({id: c.legacy_id ?? c.registro_id ?? c.id ?? null,
    ...detectar(c.titulo)}))
}}}];

// PEL | Antes da SP DEDUPLICA EDITORIAL | Run Once for All Items
// Rejeita entrada invalida antes de criar uma reserva. Preserva campos originais.
return $input.all().map((item, index) => {
  const entrada = item.json ?? {};
  function escolher(principal, alternativo, nome) {
    // O normalizador posterior usa ?? sobre Start Dedup: nao permitir que
    // campo presente e vazio seja interpretado de forma diferente aqui.
    const valor = entrada[principal] ?? entrada[alternativo];
    if (typeof valor !== 'string' || !valor.trim()) {
      throw new Error(`Entrada PEL invalida: ${nome} ausente ou nao textual (item ${index}).`);
    }
    return valor.trim();
  }
  const titulo = escolher('titulo', 'title', 'titulo/title');
  const link = escolher('link', 'url', 'link/url');
  if (titulo.length > 500) throw new Error(`Entrada PEL invalida: titulo excede 500 caracteres (item ${index}).`);
  if (link.length > 500 || !/^https?:\/\/[^\s/?#]+(?:[/?#][^\s]*)?$/i.test(link)) {
    throw new Error(`Entrada PEL invalida: link deve ser URL HTTP(S) de ate 500 caracteres (item ${index}).`);
  }
  return {json: {...entrada, titulo, link}, pairedItem: {item: index}};
});

// PEL v0.5.1 observacao. Executar APOS Similaridade Editorial v0.4.0.
// Nao altera duplicidade_editorial, roteamento, banco ou WordPress.
const entrada = $input.first()?.json ?? {};
const titulo = String(entrada.candidato?.titulo ?? '').trim();
const comparaveis = Array.isArray(entrada.comparaveis) ? entrada.comparaveis : [];
const contexto = entrada.contexto_vocabulario_pel;
function normalizar(texto) {
  return String(texto ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
}
const comuns = new Set(['que','para','com','uma','por','dos','das','uma','sobre','mais','apos','pelo','pela','ano','anos','brasil']);
function tokens(t) { return [...new Set(normalizar(t).split(' ').filter(x => x.length >= 4 && !comuns.has(x)))]; }
function fase(t) {
  const s = ` ${normalizar(t)} `;
  // Negacao ou multiplos sinais nao sao resolvidos por esta heuristica.
  if (/\b(nao|nem|nega|negou)\b/.test(s)) return null;
  const abertura = /\b(abre|abriu|abertura)\b/.test(s);
  const cancelamento = /\b(cancela|cancelou|cancelamento|cancelada|cancelado)\b/.test(s);
  if (abertura && cancelamento) return null;
  if (abertura) return 'ABERTURA';
  if (cancelamento) return 'CANCELAMENTO';
  if (/\b(aprovou|aprova|aprovado|aprovada)\b/.test(s)) return 'APROVACAO';
  if (/\b(discute|discussao|debate|debater)\b/.test(s)) return 'DISCUSSAO';
  return null;
}
const assinatura = tokens(titulo);
const resultados = comparaveis.filter(c => c && typeof c.titulo === 'string' && c.titulo.trim()).map(c => {
  const outros = tokens(c.titulo);
  const compartilhados = assinatura.filter(x => outros.includes(x));
  const iguais = titulo && normalizar(titulo) === normalizar(c.titulo);
  const faseCandidato = fase(titulo), faseComparavel = fase(c.titulo);
  let relacao = 'INDETERMINADO';
  const evidencias = [];
  if (iguais) { evidencias.push('TITULOS_NORMALIZADOS_IGUAIS'); }
  else if (compartilhados.length >= 4 && faseCandidato && faseComparavel && faseCandidato !== faseComparavel) {
    // Diferenca de fase nao prova mesmo objeto, nem ordem temporal.
    relacao = 'RELACIONADO'; evidencias.push('FASES_DISTINTAS_REQUEREM_REVISAO');
  } else if (compartilhados.length >= 4) {
    relacao = 'RELACIONADO'; evidencias.push('TOKENS_COMPARTILHADOS');
  }
  return {comparavel_id: c.legacy_id ?? c.registro_id ?? c.id ?? null, titulo: c.titulo,
    relacao_sugerida: relacao, evidencias, tokens_compartilhados: compartilhados,
    fase_candidato: faseCandidato, fase_comparavel: faseComparavel,
    ausencias: ['ENTIDADES_NAO_RESOLVIDAS','OBJETO_NAO_RESOLVIDO','DATA_EVENTO_NAO_RESOLVIDA'],
    _prioridade: iguais ? 3 : evidencias.includes('FASES_DISTINTAS_REQUEREM_REVISAO') ? 2 : relacao === 'RELACIONADO' ? 1 : 0};
});
resultados.sort((a,b) => b._prioridade - a._prioridade || b.tokens_compartilhados.length - a.tokens_compartilhados.length);
const top = resultados.slice(0, 3).map(({_prioridade, ...resto}) => resto);
return [{json: {...entrada, analise_editorial_pel: {
  versao: '0.5.1', modo: 'OBSERVACAO', aplicado_na_decisao: false,
  status: titulo ? 'ANALISADO' : 'TITULO_AUSENTE', total_comparados: resultados.length,
  vocabulario_status: contexto?.status ?? 'AUSENTE',
  relacao_sugerida: top[0]?.relacao_sugerida ?? 'INDETERMINADO', comparavel: top[0] ?? null,
  top_comparaveis: top,
  limitacoes: ['HEURISTICA_NAO_VALIDA_DUPLICIDADE', 'SEM_RESOLUCAO_DE_ENTIDADES_OU_OBJETO', 'DISTINTO_NAO_AUTOMATIZADO']
}}}];

